css:
.fx-pc{width:min(960px,100%);display:grid;gap:1.6em}
.fx-pc h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-pc .wrap{overflow-x:auto;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-pc table{border-collapse:separate;border-spacing:0;width:100%;min-width:36em;text-align:center}
.fx-pc th,.fx-pc td{padding:.85em 1em;border-bottom:1px solid var(--border);font-size:.94em}
.fx-pc tbody tr:last-child>*{border-bottom:0}
.fx-pc tbody th[scope=row]{text-align:left;font-weight:500;position:sticky;left:0;background:color-mix(in srgb,var(--surface) 94%,var(--text));z-index:1}
.fx-pc thead th{padding:1.4em 1em 1.1em;vertical-align:bottom;font-weight:400}
.fx-pc thead th:first-child{text-align:left;position:sticky;left:0;background:color-mix(in srgb,var(--surface) 94%,var(--text));z-index:1}
.fx-pc thead b{display:block;font:600 1.15em var(--font-heading)}.fx-pc thead span{display:block;font:600 1.5em var(--font-heading);color:var(--primary);margin:.15em 0}.fx-pc thead small{opacity:.6}
.fx-pc .hl{background:color-mix(in srgb,var(--primary) 7%,transparent)}
.fx-pc thead .hl{border-top:3px solid var(--accent)}
.fx-pc .grp th{text-align:left;font-size:.74em;font-weight:700;letter-spacing:.14em;text-transform:uppercase;opacity:.6;padding:1.2em 1em .5em;background:color-mix(in srgb,var(--text) 3%,transparent)}
.fx-pc td:nth-child(3){background:color-mix(in srgb,var(--primary) 7%,transparent)}
.fx-pc .yes{color:var(--accent);font-weight:800}.fx-pc .no{opacity:.35}
.fx-pc tbody tr:not(.grp):hover>*{background-color:color-mix(in srgb,var(--text) 4%,transparent)}
.fx-pc .note{font-size:.82em;opacity:.55}
/* touch: :hover mirrored as .is-tap */
.fx-pc tbody tr:not(.grp).is-tap>*{background-color:color-mix(in srgb,var(--text) 4%,transparent)}
